      if (!res.recorded) return appendFailedSummary(providerName, res.reason ?? null);
      return {
        recorded: 'unavailable',
        provider: providerName,
        input: null,
        cacheRead: null,
        output: null,
        recordId: res.recordId,
        reason: HOST_RUN_RETENTION_TRUNCATED_REASON,
